//CLOSE AND CLEAR
$('body #header-main .icon-close').on('click tap', function() {
  $('#header-search-form input#search')
    .val('')
    .focus()
    .trigger({ type: 'keypress', which: 13 });
  $('body').removeClass('search-init search-active filter-active');
  $('#header-shopping-cart a.icon-cart').delay(300).queue(function(next) {
    $('#header-shopping-cart a.icon-cart').css({ 'z-index': '1' });
    next();
  });
});
